import {
  CircleGeometry,
  Group,
  Mesh,
  MeshBasicNodeMaterial,
  PlaneGeometry,
} from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';

function createNode(config, ctx) {
  const {
    Group: ThreeGroup,
    Mesh: ThreeMesh,
    PlaneGeometry: ThreePlaneGeometry,
    CircleGeometry: ThreeCircleGeometry,
  } = ctx.THREE;

  const RootGroup = ThreeGroup || Group;
  const RootMesh = ThreeMesh || Mesh;
  const RootPlaneGeometry = ThreePlaneGeometry || PlaneGeometry;
  const RootCircleGeometry = ThreeCircleGeometry || CircleGeometry;

  const root = new RootGroup();
  root.name = 'pricing-card-2';

  const resources = [];
  const cleanupCallbacks = [];

  const colors =
    config.intent?.visualSpec?.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10',
    };

  const backdropGeometry = new RootPlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  const lowerGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 0.62, backdropY),
  );
  backdropMaterial.colorNode = mix(
    lowerGradient,
    vec3(0.13, 0.14, 0.17),
    smoothstep(0.62, 1.0, backdropY),
  );

  const backdrop = new RootMesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new RootCircleGeometry(2.05, 64);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const shadow = new RootMesh(shadowGeometry, shadowMaterial);
  shadow.name = 'card-contact-shadow';
  shadow.scale.set(1.45, 0.48, 1);
  shadow.position.set(0, -0.98, -0.22);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGeometry = new RootPlaneGeometry(3.55, 2.2);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
  });
  const card = new RootMesh(cardGeometry, cardMaterial);
  card.name = 'brushed-metal-pricing-surface';
  card.position.z = 0;
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const topAccentGeometry = new RootPlaneGeometry(3.1, 0.035);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
  });
  const topAccent = new RootMesh(topAccentGeometry, accentMaterial);
  topAccent.name = 'signal-red-machined-accent';
  topAccent.position.set(-0.02, 0.93, 0.025);
  root.add(topAccent);
  resources.push(topAccentGeometry, accentMaterial);

  const insetGeometry = new RootPlaneGeometry(3.18, 1.82);
  const insetMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.14,
  });
  const inset = new RootMesh(insetGeometry, insetMaterial);
  inset.name = 'subtle-machined-inset';
  inset.position.set(0, -0.03, 0.018);
  root.add(inset);
  resources.push(insetGeometry, insetMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !ctx.fontAtlas) continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.color ?? colors.paper,
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });
    textObject.position.set(
      item.position?.[0] ?? -1.2,
      item.position?.[1] ?? 0,
      item.position?.[2] ?? 0.05,
    );
    root.add(textObject);
  }

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        cardMaterial.map = texture;
        cardMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const primitiveResults = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;
    const result = applyPrimitive(root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      if (result.timeline?.kill) result.timeline.kill();
    }

    for (const callback of cleanupCallbacks) callback();

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.traverse((object) => {
      if (object !== root && object.userData?.cleanup) object.userData.cleanup();
    });
  };

  return root;
}

export default createNode;
